.quiz-letter {
  flex: 0 0 1.6em; height: 1.6em; line-height: 1.6em; text-align: center;
  border-radius: 50%; background: #ecf0f1; font-weight: 700; font-size: 0.85em;
}
.quiz-option.is-correct { border-color: #27ae60; background: #eafaf1; }
.quiz-option.is-correct .quiz-letter { background: #27ae60; color: #fff; }
.quiz-option.is-wrong { border-color: #e74c3c; background: #fdedec; }
.quiz-option.is-wrong .quiz-letter { background: #e74c3c; color: #fff; }

.quiz-fill { display: flex; gap: 0.5em; margin-bottom: 0.6em; }
.quiz-input {
  flex: 1; font: inherit; padding: 0.4em 0.7em;
  border: 2px solid #cfd8dc; border-radius: 8px; color: #2c3e50;
}
.quiz-input:focus { outline: none; border-color: #3498db; }
.quiz-input.is-correct { border-color: #27ae60; background: #eafaf1; }
.quiz-input.is-wrong { border-color: #e74c3c; background: #fdedec; }

.quiz-btn {
  font: inherit; cursor: pointer; border: none; border-radius: 8px;
  padding: 0.4em 1.1em; background: #3498db; color: #fff;
}
