.quiz-feedback { min-height: 1.4em; margin: 0.5em 0; line-height: 1.4; }
.quiz-feedback.is-correct { color: #1e8449; }
.quiz-feedback.is-wrong { color: #c0392b; }
.quiz-feedback.is-info { color: #2c3e50; }
